    "length_overall_m": {
      "type": "number",
      "minimum": 0,
      "maximum": 300
    },
    "displacement_tons": {
      "type": "number",
      "minimum": 0
    },
    "crew_capacity": {
      "type": "integer",
      "minimum": 1
    },
    "propulsion": {
      "type": "object",
      "properties": {
        "drive_type": {
          "type": "string"
        },
        "max_speed_knots": {
          "type": "number",
          "minimum": 0
        }
      },
      "required": ["drive_type"]
    },
    "beta_core": {
      "type": "object",
      "properties": {
        "core_id": {
          "type": "string"
        },
        "operational": {
          "type": "boolean",
          "default": true
        }
      },
      "required": ["core_id", "operational"]
    },
    "missions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "examples": [["[placeholder_mission]"]]
    }
  },
  "required": ["vessel_name", "classification", "beta_core"],
  "additionalProperties": false
}
